	@EventHandler( payloadType=UnAssignCustomerFromBeneficiaryEvent.class)
	public void handle( UnAssignCustomerFromBeneficiaryEvent event) {
	    LOGGER.info("handling UnAssignCustomerFromBeneficiaryEvent - " + event );

	    // ------------------------------------------
	    // delegate to unAssignFrom
	    // ------------------------------------------
	    Beneficiary entity = unAssignCustomer( event.getBeneficiaryId() );

		// ------------------------------------------
		// emit to subscribers that find one
		// ------------------------------------------    	
	    emitFindBeneficiary( entity );
	
		// ------------------------------------------
		// emit to subscribers that find all
		// ------------------------------------------    	
	    emitFindAllBeneficiary( entity );
	}




    /**
     * Method to retrieve the Beneficiary via an BeneficiaryPrimaryKey.
     * @param 	id Long
     * @return 	Beneficiary
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Beneficiary handle( FindBeneficiaryQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getBeneficiaryId() );
    }
    
    /**
     * Method to retrieve a collection of all Beneficiarys
     *
     * @param	query	FindAllBeneficiaryQuery 
     * @return 	List<Beneficiary> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Beneficiary> handle( FindAllBeneficiaryQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindBeneficiary,
 * but only if the id matches
 *
 * @param		entity	Beneficiary
 */
	protected void emitFindBeneficiary( Beneficiary entity ) {
		LOGGER.info("handling emitFindBeneficiary" );
		
	    queryUpdateEmitter.emit(FindBeneficiaryQuery.class,
	                            query -> query.getFilter().getBeneficiaryId().equals(entity.getBeneficiaryId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllBeneficiary
	 * 
	 * @param		entity	Beneficiary
	 */
	protected void emitFindAllBeneficiary( Beneficiary entity ) {
		LOGGER.info("handling emitFindAllBeneficiary" );
		
	    queryUpdateEmitter.emit(FindAllBeneficiaryQuery.class,
	                            query -> true,
	                            entity);
	}

